WITH filtered_accounts AS (SELECT * FROM accounts WHERE customer_id IN (14, 26, 35)), status_group_summary AS (SELECT CASE WHEN status IN ('FROZEN', 'OPEN') THEN 'core' ELSE 'other' END AS status_group, ROUND((100 * SUM(CASE WHEN account_type = 'CREDIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_credit FROM filtered_accounts GROUP BY CASE WHEN status IN ('FROZEN', 'OPEN') THEN 'core' ELSE 'other' END) SELECT status_group, pct_credit FROM status_group_summary ORDER BY pct_credit;
